INSERT INTO permissions(code) VALUES ('attendance.adjust'),('attendance.approve'),('time_records.view'),('time_records.create_manual'),('time_records.correct'),('time_records.ingest'),('schedules.view'),('schedules.create'),('schedules.update'),('schedules.assign'),('leave.view'),('leave.create'),('leave.approve'),('leave.reject'),('leave.cancel'),('leave.configure');
INSERT INTO role_permissions SELECT r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('administrator','payroll_manager') AND (p.code LIKE 'attendance.%' OR p.code LIKE 'time_records.%' OR p.code LIKE 'schedules.%' OR p.code LIKE 'leave.%') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('payroll_clerk','viewer') AND p.code IN ('time_records.view','schedules.view','leave.view') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.code='payroll_clerk' AND p.code IN ('time_records.create_manual','leave.create') ON CONFLICT DO NOTHING;
